    function tierFor(pct) { for (var i = 0; i < TIERS.length; i++) { if (pct >= TIERS[i].min) { return TIERS[i]; } } return TIERS[TIERS.length - 1]; }

    /* Debrief texts. A pattern is named only when the run shows it (EQIL item 13). */
