            junior: T('Identificaste lo más visible; los problemas que deciden el futuro estaban en márgenes, retención y gobierno.', 'You identified the most visible issues; the problems that decide the future were in margins, retention and governance.'),
            apprentice: T('Leer un P&L es leer decisiones: empieza por el runway, el margen bruto y la economía unitaria, y verifica cada cifra antes de señalarla.', 'Reading a P&L is reading decisions: start with runway, gross margin and unit economics, and check every figure before flagging it.')
        },
        q: [
            T('¿Qué señal de esta empresa habrías querido ver dos trimestres antes, y qué dato del P&L te la habría dado?', 'Which signal in this company would you have wanted to see two quarters earlier, and which P&L figure would have shown it?'),
            T('Una lista corta obliga a dejar cosas fuera. ¿Con qué criterio decidiste que una línea no merecía estar, y lo sostendrías ante los fundadores?', 'A short list forces you to leave things out. What rule did you use to decide a line did not belong, and would you defend it to the founders?'),
            T('Si fueras el Fondo Horizonte, ¿qué tres preguntas harías sobre estos siete trimestres antes de invertir?', 'If you were Fondo Horizonte, which three questions would you ask about these seven quarters before investing?')
        ],
        done: T('Completaste las siete revisiones trimestrales. El resumen final muestra tu precisión y lo que dejó ver tu recorrido.', 'You have completed the seven quarterly reviews. The final summary shows your accuracy and what your run revealed.'),
        group: T('Problemas candidatos de la ronda', 'Candidate problems for this round')
    };
    var SIGNALS = {
        scaleMiss: ['r1p2', 'r2p4', 'r3p2', 'r4p1'], scaleTick: ['r1p6', 'r2p6', 'r6p6'],
        growthMiss: ['r2p2', 'r3p1', 'r3p3', 'r4p2', 'r5p3', 'r6p1', 'r6p4'], growthTick: ['r3p5', 'r2p5'],
        hiddenMiss: ['r2p1', 'r2p3']
    };
    function fill(s, o) { return String(s).replace(/\{(\w+)\}/g, function (m, k) { return o[k] !== undefined ? o[k] : m; }); }
    var ADAPTER = null;

    class PLDiagnosticAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Diagnostico P&L: De Garage a Serie A';
            this.version = '2.0.0';
            this.ROUNDS = ROUNDS;
            this.CASH_VALUES = CASH;
            this._pendingAdvance = null;
            this._fb = null;
            this._busBound = false;
            ADAPTER = this;
        }

        initialize(state) {
            /* Reset on a fresh start or when no completed round remains (undo back to the start). */
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = {
                    totalScore: 0,
                    maxPossibleScore: 0,
                    roundScores: [],
                    roundMaxScores: [],
                    correctCounts: [],
                    totalCorrects: [],
                    percentages: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { selectedProblems: '' };
            }
            this._bindModalClose();
            this._bindEvents();
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var selected = [];
            var allCbs = document.getElementsByClassName('pl421-problem-checkbox');
            for (var j = 0; j < allCbs.length; j++) {
                if (allCbs[j].checked) selected.push(allCbs[j].value);
            }
            if (selected.length === 0) {
                window.mySimulation.uiManager.showNotification(tr('no_selection_warning'), 'warning');
                return false;
            }
            decisions.selectedProblems = selected.join(',');
            return true;
        }

        calculateResults(state) {
            var out = this._computeRound(state);
            return {
                period: out.period,
                roundName: out.roundName,
                score: out.score,
                maxScore: out.maxScore,
                correctFound: out.correctFound,
                totalCorrect: out.totalCorrect,
                penalty: out.penalty,
                percentage: out.percentage,
                totalScore: out.totalScore,
                totalMaxScore: out.totalMaxScore,
                overallScore: out.overallScore,
                selected: out.selected,
                falseAlarms: out.falseAlarms
            };
        }

        /* Scoring as in the case, Exhibit 2: points of the real problems found, minus 5 per flag on a healthy line, floor 0;
           the grade is cumulative accuracy (points obtained over points possible). */
        _computeRound(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var selected = String(state.decisions.selectedProblems || '').split(',').filter(function (x) { return x; });
            var score = 0, maxScore = 0, correctFound = 0, totalCorrect = 0, penalty = 0, falseAlarms = 0;
            round.problems.forEach(function (p) {
                if (p.correct) {
                    maxScore += p.points;
                    totalCorrect++;
                    if (selected.indexOf(p.id) !== -1) { score += p.points; correctFound++; }
                } else if (selected.indexOf(p.id) !== -1) {
                    penalty += 5;
                    falseAlarms++;
                }
            });
            var finalScore = Math.max(0, score - penalty);
            var pct = maxScore > 0 ? Math.round((finalScore / maxScore) * 100) : 0;
            var ds = state.domainState;
            ds.totalScore += finalScore;
            ds.maxPossibleScore += maxScore;
            ds.roundScores.push(finalScore);
            ds.roundMaxScores.push(maxScore);
            ds.correctCounts.push(correctFound);
            ds.totalCorrects.push(totalCorrect);
            ds.percentages.push(pct);
            var overallScore = ds.maxPossibleScore > 0 ? Math.round((ds.totalScore / ds.maxPossibleScore) * 100) : 0;
            overallScore = Math.max(0, Math.min(100, overallScore));
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: overallScore });
            ds.performanceTier = tierFor(overallScore).id;

            this._fb = { idx: idx, selected: selected, score: finalScore, maxScore: maxScore, correctFound: correctFound, totalCorrect: totalCorrect, penalty: penalty, period: period };
            this._showFeedbackModal();

            var self = this;
            var maxP = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.maxPeriods) || this.ROUNDS.length;
            /* Without a framework event bus, the next round is drawn when the feedback closes (fallback only). */
            this._pendingAdvance = (!this._busBound && period < maxP) ? function () {
                self._updateBriefing({ currentPeriod: period + 1, domainState: state.domainState, history: [] });
            } : null;

            return {
                period: period, roundName: L(round.title), score: finalScore, maxScore: maxScore, correctFound: correctFound,
                totalCorrect: totalCorrect, penalty: penalty, percentage: pct, totalScore: ds.totalScore, totalMaxScore: ds.maxPossibleScore,
                overallScore: overallScore, selected: selected, falseAlarms: falseAlarms
            };
        }

        /* The screen follows the framework state: the next round is drawn when the period advances, not when a dialog closes. */
        _bindEvents() {
            var fw = window.mySimulation, self = this;
            if (!this._docBound) {
                this._docBound = true;
                document.addEventListener('express:langchanged', function () { self._repaint(); });
            }
            if (this._busBound || !fw || !fw.eventBus || typeof fw.eventBus.on !== 'function') { return; }
            this._busBound = true;
            fw.eventBus.on('period:submitted', function () { self._updateBriefing(fw.state); });
            fw.eventBus.on('period:undone', function () { self._updateBriefing(fw.state); });
            fw.eventBus.on('language:changed', function () { self._repaint(); });
        }

        _isComplete(state) {
            var h = (state && state.history) || [];
            return h.length >= this.ROUNDS.length;
        }

        _repaint() {
            var fw = window.mySimulation;
            if (!fw || !fw.state) { return; }
            this._updateBriefing(fw.state, true);
            var modal = document.getElementById('roundFeedbackModal');
            if (modal && modal.classList.contains('pl421-modal-open') && this._fb) { this._showFeedbackModal(true); }
            var content = document.getElementById('usf-completion-content') || document.getElementById('completionContent');
            if (content && this._isComplete(fw.state) && content.querySelector('.pl421-cm')) {
                try { content.innerHTML = this.formatCompletionMessage(this.getPerformanceSummary(fw.state.history)); } catch (e) {}
            }
            try { if (typeof fw.renderHistoryTable === 'function') { fw.renderHistoryTable(); } } catch (e) {}
        }

        _bindModalClose() {
            var self = this;
            var overlay = document.getElementById('roundFeedbackOverlay');
            var btn = document.getElementById('modalContinueBtn');
            var modal = document.getElementById('roundFeedbackModal');
            if (btn && !btn._pl421Bound) {
                btn.addEventListener('click', function () { self._closeModal(); });
                btn._pl421Bound = true;
            }
            if (overlay && !overlay._pl421Bound) {
                overlay.addEventListener('click', function () { self._closeModal(); });
                overlay._pl421Bound = true;
            }
            if (modal && !modal._pl421KeyBound) {
                document.addEventListener('keydown', function (e) {
                    if (e.key === 'Escape' && modal.classList.contains('pl421-modal-open')) { self._closeModal(); }
                });
                modal._pl421KeyBound = true;
            }
        }

        _closeModal() {
            var modal = document.getElementById('roundFeedbackModal');
            if (modal) {
                modal.classList.remove('pl421-modal-open');
                modal.setAttribute('aria-hidden', 'true');
            }
            document.body.style.overflow = '';
            if (typeof this._pendingAdvance === 'function') {
                var fn = this._pendingAdvance;
                this._pendingAdvance = null;
                fn();
            }
            var focusTo = document.getElementById('roundTitle');
            if (focusTo && typeof focusTo.focus === 'function') { try { focusTo.focus(); } catch (e) {} }
        }

        _showFeedbackModal(repaintOnly) {
            this._bindModalClose();
            var fb = this._fb;
            var modal = document.getElementById('roundFeedbackModal');
            var titleEl = document.getElementById('modalRoundTitle');
            var scoreEl = document.getElementById('modalRoundScore');
            var bodyEl = document.getElementById('modalRoundBody');
            var btnEl = document.getElementById('modalContinueBtn');
            if (!fb || !modal || !titleEl || !scoreEl || !bodyEl) return;
            var round = this.ROUNDS[fb.idx];
            titleEl.innerHTML = L(round.title);
            var scoreHtml = '<span class="pl421-score-big">' + fb.score + ' / ' + fb.maxScore + '</span> ' + tr('points_label');
            if (fb.penalty > 0) {
                scoreHtml += ' · <span class="pl421-fb-penalty">' + tr('penalty_label') + ': -' + fb.penalty + '</span>';
            }
            scoreHtml += '<br><span class="pl421-fb-count">' + fb.correctFound + ' ' + tr('of_label') + ' ' + fb.totalCorrect + ' ' + tr('correct_identified') + '</span>';
            scoreEl.innerHTML = scoreHtml;
            var html = '';
            ordered(round.problems, fb.idx).forEach(function (p) {
                var was = fb.selected.indexOf(p.id) !== -1;
                if (p.correct && was) {
                    html += '<div class="pl-diag-fb-correct"><span aria-hidden="true">✓ </span><strong>' + L(p.text) + '</strong><br>' + L(p.why) + '</div>';
                } else if (p.correct && !was) {
                    html += '<div class="pl-diag-fb-missed"><span aria-hidden="true">✗ </span><strong>' + tr('missed_label') + ':</strong> ' + L(p.text) + '<br>' + L(p.why) + '</div>';
                } else if (!p.correct && was) {
                    html += '<div class="pl-diag-fb-wrong"><span aria-hidden="true">! </span><strong>' + tr('wrong_label') + ':</strong> ' + L(p.text) + '<br>' + L(p.why) + '</div>';
                }
            });
            html += '<div class="pl-diag-fb-lesson"><strong>' + tr('lesson_label') + ':</strong> ' + L(round.lesson) + '</div>';
            bodyEl.innerHTML = html;
            if (btnEl) {
                btnEl.textContent = (fb.period >= this.ROUNDS.length) ? tr('finish_btn') : tr('continue_btn');
            }
            if (repaintOnly) { return; }
            modal.classList.add('pl421-modal-open');
            modal.setAttribute('aria-hidden', 'false');
            document.body.style.overflow = 'hidden';
            var dialog = modal.querySelector('.pl421-modal-dialog');
            if (dialog) dialog.scrollTop = 0;
            if (btnEl && typeof btnEl.focus === 'function') { try { btnEl.focus(); } catch (e) {} }
        }

        _pnlHtml(round) {
            var h = '<table class="table pl-diag-pnl"><caption class="pl421-sr-only">' + esc(L(round.title)) + '</caption><thead><tr>';
            L(round.cols).forEach(function (c) { h += '<th scope="col">' + c + '</th>'; });
            h += '</tr></thead><tbody>';
            round.pnl.forEach(function (r) {
                var cls = r[4] || '';
                if (cls === 'sec') { h += '<tr class="pl421-pnl-sec"><td colspan="4">' + L(r[0]) + '</td></tr>'; return; }
                var trc = cls === 'rev' ? 'pl-diag-pnl-revenue' : cls === 'tot' ? 'pl-diag-pnl-total' : cls === 'neg' ? 'pl-diag-pnl-negative' : '';
                var strong = cls === 'tot' || cls === 'neg' || cls === 'bold' || cls === 'rev';
                var cell = function (v) {
                    var s = (v === null || v === undefined) ? '' : L(v);
                    var neg = typeof v === 'number' && v < 0;
                    return '<td' + (neg ? ' class="pl421-neg"' : '') + '>' + (strong && s !== '' ? '<strong>' + s + '</strong>' : s) + '</td>';
                };
                h += '<tr' + (trc ? ' class="' + trc + '"' : '') + '><td>' + (strong ? '<strong>' + L(r[0]) + '</strong>' : L(r[0])) + '</td>' + cell(r[1]) + cell(r[2]) + cell(r[3]) + '</tr>';
            });
            return h + '</tbody></table>';
        }

        _metricsHtml(round) {
            if (!round.metrics) { return ''; }
            var h = '<table class="table pl-diag-metrics"><thead><tr>';
            L(round.metrics.cols).forEach(function (c) { h += '<th scope="col">' + c + '</th>'; });
            h += '</tr></thead><tbody>';
            round.metrics.rows.forEach(function (r) { h += '<tr><td>' + L(r[0]) + '</td><td>' + L(r[1]) + '</td><td>' + L(r[2]) + '</td></tr>'; });
            return h + '</tbody></table>';
        }

        _updateBriefing(state, keepChecks) {
            state = state || {};
            var done = this._isComplete(state);
            var idx = Math.max(0, Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1));
            var round = this.ROUNDS[idx];
            var titleEl = document.getElementById('roundTitle');
            if (titleEl) { titleEl.innerHTML = L(round.title); titleEl.setAttribute('tabindex', '-1'); }
            var ctxEl = document.getElementById('roundContext');
            if (ctxEl) ctxEl.innerHTML = L(round.context);
            var pnlEl = document.getElementById('pnlContainer');
            if (pnlEl) pnlEl.innerHTML = this._pnlHtml(round);
            var metEl = document.getElementById('metricsContainer');
            if (metEl) metEl.innerHTML = this._metricsHtml(round);

            var probEl = document.getElementById('problemsContainer');
            if (probEl) {
                var keep = {};
                if (keepChecks) {
                    Array.prototype.forEach.call(probEl.querySelectorAll('.pl421-problem-checkbox'), function (cb) { if (cb.checked) keep[cb.value] = true; });
                }
                var html = '';
                if (done) {
                    html = '<p class="pl421-done-note">' + L(DB.done) + '</p>';
                } else {
                    html = '<fieldset class="pl421-fieldset"><legend class="pl421-sr-only">' + L(DB.group) + '</legend>';
                    ordered(round.problems, idx).forEach(function (p) {
                        var cid = 'pl421cb_' + p.id;
                        html += '<label class="pl421-sim-problem-item' + (keep[p.id] ? ' selected' : '') + '" for="' + cid + '">';
                        html += '<input type="checkbox" class="pl421-problem-checkbox" id="' + cid + '" value="' + p.id + '"' + (keep[p.id] ? ' checked' : '') + '>';
                        html += '<span>' + L(p.text) + '</span>';
                        html += '</label>';
                    });
                    html += '</fieldset>';
                }
                probEl.innerHTML = html;
                Array.prototype.forEach.call(probEl.querySelectorAll('.pl421-problem-checkbox'), function (cb) {
                    cb.addEventListener('change', function () {
                        var item = cb.closest('.pl421-sim-problem-item');
                        if (item) item.classList.toggle('selected', cb.checked);
                    });
                });
            }

            var cashEl = document.getElementById('cashDisplay');
            if (cashEl) {
                var cashIdx = Math.min((state.currentPeriod || 1), this.CASH_VALUES.length - 1);
                cashEl.textContent = 'USD ' + num(this.CASH_VALUES[cashIdx]);
            }
            var accEl = document.getElementById('accuracyDisplay');
            if (accEl && state.domainState && state.domainState.maxPossibleScore > 0) {
                accEl.textContent = Math.round((state.domainState.totalScore / state.domainState.maxPossibleScore) * 100) + (lang() === 'en' ? '%' : ' %');
            } else if (accEl) {
                accEl.textContent = lang() === 'en' ? '0%' : '0 %';
            }
            var corrEl = document.getElementById('correctDisplay');
            if (corrEl && state.domainState && state.domainState.correctCounts) {
                var sumCorr = state.domainState.correctCounts.reduce(function (a, b) { return a + b; }, 0);
                var sumTotal = state.domainState.totalCorrects.reduce(function (a, b) { return a + b; }, 0);
                corrEl.textContent = sumCorr + ' / ' + sumTotal;
            }
            if (!keepChecks) {
                try { window.scrollTo({ top: 0, behavior: 'smooth' }); } catch (e) {}
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.totalScore', function (v) { return Math.round(v || 0) + ' pts'; });
            this._bindEvents();
        }

        getChartConfig() {
            var en = lang() === 'en';
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: en ? 'Points obtained' : 'Puntos obtenidos',
                            data: [],
                            backgroundColor: 'rgba(99,102,241,0.75)',
                            borderColor: '#818cf8',
                            borderWidth: 2,
                            borderRadius: 8
                        }, {
                            label: en ? 'Maximum possible' : 'Máximo posible',
                            data: [],
                            backgroundColor: 'rgba(34,211,238,0.18)',
                            borderColor: 'rgba(34,211,238,0.55)',
                            borderWidth: 1,
                            borderDash: [5, 4],
                            borderRadius: 8
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { labels: { color: '#d4dbf5', font: { size: 12 } } },
                            title: { display: false }
                        },
                        scales: {
                            x: { ticks: { color: '#9aa6cf' }, grid: { color: 'rgba(255,255,255,0.05)' } },
                            y: {
                                beginAtZero: true,
                                ticks: { color: '#9aa6cf' },
                                grid: { color: 'rgba(255,255,255,0.08)' },
                                title: { display: true, text: en ? 'Points' : 'Puntos', color: '#a5b4fc' }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var scores = ds.roundScores || [], maxes = ds.roundMaxScores || [];
            var labels = scores.map(function (_, i) { return 'R' + (i + 1); });
            try {
                var cv = document.getElementById('scoreChart');
                if (cv) {
                    cv.setAttribute('role', 'img');
                    var parts = scores.map(function (s, i) { return 'R' + (i + 1) + ': ' + s + '/' + (maxes[i] || 0); });
                    cv.setAttribute('aria-label', (lang() === 'en' ? 'Points by round. ' : 'Puntos por ronda. ') + parts.join('; '));
                }
            } catch (e) {}
            return { scoreChart: { labels: labels, datasets: [{ data: scores }, { data: maxes }] } };
        }

        getPerformanceSummary(history) {
            history = history || [];
            if (!history.length) return {};
            var self = this;
            var totalScore = 0, totalMax = 0, totalCorrect = 0, totalProblems = 0, wrongTicked = 0, wrongTotal = 0;
            var picked = {}, rows = [];
            history.forEach(function (h) {
                var r = h.results || {};
                totalScore += r.score || 0;
                totalMax += r.maxScore || 0;
                totalCorrect += r.correctFound || 0;
                totalProblems += r.totalCorrect || 0;
                var p = parseInt(r.period !== undefined ? r.period : h.period, 10);
                var round = self.ROUNDS[Math.max(0, Math.min((p || 1) - 1, self.ROUNDS.length - 1))];
                var sel = Array.isArray(r.selected) ? r.selected : String((h.decisions && h.decisions.selectedProblems) || '').split(',');
                sel.forEach(function (id) { if (id) picked[id] = true; });
                round.problems.forEach(function (q) { if (!q.correct) { wrongTotal++; if (sel.indexOf(q.id) !== -1) wrongTicked++; } });
                rows.push({ p: p, round: round, sel: sel, pct: r.maxScore > 0 ? Math.round(100 * (r.score || 0) / r.maxScore) : 0 });
            });
            var pct = totalMax > 0 ? Math.round((totalScore / totalMax) * 100) : 0;
            pct = Math.max(0, Math.min(100, pct));
            var tier = tierFor(pct);
            var coverage = totalProblems > 0 ? Math.round(100 * totalCorrect / totalProblems) : 0;
            var discipline = wrongTotal > 0 ? Math.round(100 * (1 - wrongTicked / wrongTotal)) : 100;

            /* turning point: the weakest round, earliest on a tie */
            var worst = null;
            rows.forEach(function (x) { if (!worst || x.pct < worst.pct) worst = x; });
            var turning = null;
            if (worst && worst.pct < 100) {
                var miss = null, wrong = null;
                worst.round.problems.forEach(function (q) {
                    var was = worst.sel.indexOf(q.id) !== -1;
                    if (q.correct && !was && (!miss || q.points > miss.points)) miss = q;
                    if (!q.correct && was && !wrong) wrong = q;
                });
                turning = { round: worst.p, pct: worst.pct, kind: miss ? 'miss' : 'wrong', id: (miss || wrong || {}).id || null };
            }

            /* patterns, from the run only */
            var all = [];
            this.ROUNDS.forEach(function (r) { all = all.concat(r.problems); });
            var seen = {};
            rows.forEach(function (x) { x.round.problems.forEach(function (q) { seen[q.id] = true; }); });
            var missed = function (ids) { return ids.filter(function (id) { return seen[id] && !picked[id]; }).length; };
            var ticked = function (ids) { return ids.filter(function (id) { return picked[id]; }).length; };
            var ofKind = function (k, correct) { return all.filter(function (q) { return q.kind === k && q.correct === correct; }).map(function (q) { return q.id; }); };
            var found = [];
            var payMiss = missed(ofKind('pay', true));
            if (payMiss >= 2) found.push({ id: 'pay', n: payMiss, w: payMiss * 10 });
            var smallTick = ticked(ofKind('small', false));
            if (smallTick >= 2) found.push({ id: 'small', n: smallTick, w: smallTick * 5 });
            var scaleSig = missed(SIGNALS.scaleMiss) + ticked(SIGNALS.scaleTick);
            if (scaleSig >= 2) found.push({ id: 'scale', n: scaleSig, w: scaleSig * 8 });
            var growthSig = missed(SIGNALS.growthMiss) + ticked(SIGNALS.growthTick);
            if (growthSig >= 2) found.push({ id: 'growth', n: growthSig, w: growthSig * 8 });
            var hiddenSig = missed(SIGNALS.hiddenMiss);
            if (hiddenSig >= 1) found.push({ id: 'hidden', n: hiddenSig, w: hiddenSig * 10 });
            var cutTick = ticked(ofKind('cut', false));
            if (cutTick >= 2) found.push({ id: 'cut', n: cutTick, w: cutTick * 5 });
            var misTick = ticked(ofKind('misread', false));
            if (misTick >= 2) found.push({ id: 'misread', n: misTick, w: misTick * 5 });
            found.sort(function (a, b) { return b.w - a.w; });
            found = found.slice(0, 3);

            return {
                totalPeriods: history.length,
                totalScore: totalScore,
                totalMax: totalMax,
                percentage: pct,
                composite: pct,
                overallScore: pct,
                score: pct,
                performance: tier.id,
                performanceKey: tier.id,
                performanceTier: tier.id,
                performanceLabel: L(tier.label),
                correctFound: totalCorrect,
                totalProblems: totalProblems,
                falseAlarms: wrongTicked,
                coverage: coverage,
                discipline: discipline,
                outcomeScore: pct,
                processScore: Math.round((coverage + discipline) / 2),
                correctIdentifications: totalCorrect + (lang() === 'en' ? ' of ' : ' de ') + totalProblems,
                turningPoint: turning,
                mistakes: found.map(function (f) { return f.id; }),
                _found: found,
                insights: this._insights({ totalCorrect: totalCorrect, totalProblems: totalProblems, coverage: coverage, wrongTicked: wrongTicked, turning: turning, found: found, tier: tier.id })
            };
        }

        _turnText(t) {
            if (!t) { return L(DB.noTurn); }
            var q = null;
            this.ROUNDS.forEach(function (r) { r.problems.forEach(function (x) { if (x.id === t.id) q = x; }); });
            return fill(L(t.kind === 'miss' ? DB.turnMiss : DB.turnWrong), { r: t.round, p: t.pct, x: q ? L(q.text) : '' });
        }

        _insights(o) {
            var out = [fill(L(DB.cov), { f: o.totalCorrect, t: o.totalProblems, c: o.coverage, w: o.wrongTicked }), this._turnText(o.turning)];
            o.found.forEach(function (f) { out.push(fill(L(DB[f.id]), { n: f.n })); });
            if (out.length < 5) out.push(L(DB.tier[o.tier]));
            return out.slice(0, 5);
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            if (summary.percentage === undefined) {
                try { summary = this.getPerformanceSummary(window.mySimulation.state.history); } catch (e) {}
            }
            var pctSign = lang() === 'en' ? '%' : ' %';
            var tier = tierFor(summary.percentage || 0);
            var ins = this._insights({ totalCorrect: summary.correctFound || 0, totalProblems: summary.totalProblems || 0, coverage: summary.coverage || 0,
                wrongTicked: summary.falseAlarms || 0, turning: summary.turningPoint || null, found: summary._found || [], tier: tier.id });
            var h = '<div class="pl421-cm" lang="' + lang() + '">';
            h += '<div class="pl421-cm-head"><div class="pl421-cm-score">' + (summary.percentage || 0) + '<span>/100</span></div>';
            h += '<div class="pl421-cm-verdict pl421-cm-tier-' + tier.id + '">' + esc(L(tier.label)) + '</div>';
            h += '<h3 class="pl421-cm-title">' + L(DB.title) + '</h3></div>';
            h += '<div class="pl421-cm-kpis">';
            h += '<div class="pl421-cm-kpi"><span class="pl421-cm-kpi-l">' + L(DB.outcome) + ' · ' + L(DB.precision) + '</span><strong>' + (summary.percentage || 0) + pctSign + '</strong></div>';
            h += '<div class="pl421-cm-kpi"><span class="pl421-cm-kpi-l">' + L(DB.points) + '</span><strong>' + (summary.totalScore || 0) + ' / ' + (summary.totalMax || 0) + '</strong></div>';
            h += '<div class="pl421-cm-kpi"><span class="pl421-cm-kpi-l">' + L(DB.process) + ' · ' + L(DB.coverage) + '</span><strong>' + (summary.coverage || 0) + pctSign + '</strong></div>';
            h += '<div class="pl421-cm-kpi"><span class="pl421-cm-kpi-l">' + L(DB.process) + ' · ' + L(DB.discipline) + '</span><strong>' + (summary.discipline === undefined ? 100 : summary.discipline) + pctSign + '</strong></div>';
            h += '</div>';
            h += '<h4 class="pl421-cm-h">' + L(DB.turning) + '</h4><p class="pl421-cm-turn">' + this._turnText(summary.turningPoint || null) + '</p>';
            h += '<h4 class="pl421-cm-h">' + L(DB.insights) + '</h4><ul class="pl421-cm-list">';
            ins.slice(2).forEach(function (s) { h += '<li>' + s + '</li>'; });
            h += '<li>' + ins[0] + '</li></ul>';
            h += '<h4 class="pl421-cm-h">' + L(DB.questions) + '</h4><ol class="pl421-cm-list">';
            DB.q.forEach(function (q) { h += '<li>' + L(q) + '</li>'; });
            h += '</ol></div>';
            return h;
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.percentage >= 85) return tr('hint_excellent');
            if (results.percentage >= 60) return tr('hint_good');
            if (results.percentage >= 30) return tr('hint_fair');
            return tr('hint_needs_work');
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.period', label: 'Ronda', i18nKey: 'col_round', formatter: function (v) {
                    var r = self.ROUNDS[Math.max(0, Math.min((parseInt(v, 10) || 1) - 1, self.ROUNDS.length - 1))];
                    return String(L(r.title)).split(':')[0];
                } },
                { key: 'results.score', label: 'Puntos', i18nKey: 'col_score', formatter: function (v) { return v + ' pts'; } },
                { key: 'results.maxScore', label: 'Maximo', i18nKey: 'col_max', formatter: function (v) { return v + ' pts'; } },
                { key: 'results.percentage', label: 'Precision', i18nKey: 'col_pct', formatter: function (v) { return v + (lang() === 'en' ? '%' : ' %'); } },
                { key: 'results.correctFound', label: 'Aciertos', i18nKey: 'col_correct', formatter: function (v) { return v || 0; } }
            ];
        }

